public static class DSPPadIntegrationRegression {
 [Serializable]public sealed class Check {public string name,evidence;public bool passed;}
 [Serializable]public sealed class Report {public string batchIdentifier,buildVersion,phase;public bool completed;public List<Check> checks=new List<Check>();public List<string> errors=new List<string>();public string limits="Programmatic input and local document-provider callbacks. Actual iCloud download/upload, physical keys/fingers and provider account state remain unverified.";}
