 static void Write(){File.WriteAllText(Path.Combine(Application.persistentDataPath,reportFile),JsonUtility.ToJson(report,true));}
 static void Note(string name,bool passed,string evidence=""){report.checks.Add(new Check{name=name,passed=passed,evidence=evidence});Write();}
 static IEnumerator Wait(float n=.5f){yield return new WaitForSecondsRealtime(n);}
 static IEnumerator Done(){float until=Time.realtimeSinceStartup+30;while(DSPPadDocuments.Busy&&Time.realtimeSinceStartup<until)yield return Wait(.25f);Note("document operation completed",!DSPPadDocuments.Busy,DSPPadDocuments.LastStatus+": "+DSPPadDocuments.LastMessage);}
 static void Observe(bool key=false,Vector2 delta=default(Vector2),float wheel=0,bool down=false,bool held=false,bool finger=false,bool fingerHeld=false,bool transaction=false){DSPPadInputMode.Observe(key,delta,wheel,down,held,finger,fingerHeld,transaction);}
 static IEnumerator Modes(){if(!DSPTouchControls.Enabled)yield break;DSPPadInputMode.SetPreference(DSPPadInputMode.Choice.Automatic);Observe(finger:true);yield return Wait();Note("direct touch selects touch",DSPPadInputMode.UseTouch);Observe(delta:new Vector2(.3f,0));yield return Wait(.25f);Note("pointer jitter does not switch",DSPPadInputMode.UseTouch);Observe(delta:new Vector2(12,0));yield return Wait();Note("pointer movement selects keyboard",!DSPPadInputMode.UseTouch);Observe(held:true,finger:true);Note("drag defers mode switch",!DSPPadInputMode.UseTouch);yield return Wait();Observe();yield return Wait();Note("after release selects touch",DSPPadInputMode.UseTouch);Observe(key:true);yield return Wait();Note("keyboard action selects keyboard",!DSPPadInputMode.UseTouch);DSPPadInputMode.SetPreference(DSPPadInputMode.Choice.Touch);yield return Wait();Observe(key:true,delta:new Vector2(20,0));Note("fixed touch ignores keyboard mode request",DSPPadInputMode.UseTouch);DSPPadInputMode.SetPreference(DSPPadInputMode.Choice.Keyboard);yield return Wait();Observe(finger:true);Note("fixed keyboard ignores touch mode request",!DSPPadInputMode.UseTouch);DSPPadInputMode.SetPreference(DSPPadInputMode.Choice.Automatic);Observe(finger:true);yield return Wait();Note("automatic restored",DSPPadInputMode.UseTouch);}
 [DllImport("@rpath/UnityFramework.framework/UnityFramework")]static extern int DSPAOTQueueTestPointer(float x,float y,int buttons,float dx,float dy,float wheel);
 static Rect Bounds(RectTransform rt){var cs=new Vector3[4];rt.GetWorldCorners(cs);var canvas=rt.GetComponentInParent<Canvas>();var camera=canvas.renderMode==RenderMode.ScreenSpaceOverlay?null:canvas.worldCamera;var a=RectTransformUtility.WorldToScreenPoint(camera,cs[0]);var b=RectTransformUtility.WorldToScreenPoint(camera,cs[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
 static void Layout(bool save){
  var ui=UIRoot.instance;var template=save?ui.saveGameWindow.cancelButton:ui.loadGameWindow.cancelButton;var a=DSPPadDocuments.FileButton(save,false);var b=DSPPadDocuments.FileButton(save,true);bool style=a&&b;
  foreach(var x in new[]{a,b}){if(!x){style=false;continue;}var t=x.GetComponentInChildren<Text>();var original=template.GetComponentInChildren<Text>();style&=t.font==original.font&&t.fontSize==original.fontSize&&x.GetComponent<Image>().sprite==template.GetComponent<Image>().sprite&&((RectTransform)x.transform).sizeDelta==((RectTransform)template.transform).sizeDelta&&x.transitions.Length==template.transitions.Length;for(int i=0;i<Math.Min(x.transitions.Length,template.transitions.Length);i++)style&=x.transitions[i].normalColor==template.transitions[i].normalColor&&x.transitions[i].mouseoverColor==template.transitions[i].mouseoverColor&&x.transitions[i].pressedColor==template.transitions[i].pressedColor;}
  Note((save?"save":"load")+" file buttons use original style",style);if(!a||!b)return;var ar=Bounds((RectTransform)a.transform);var br=Bounds((RectTransform)b.transform);bool clear=!ar.Overlaps(br)&&ar.xMin>=0&&ar.yMin>=0&&br.xMax<=Screen.width&&br.yMax<=Screen.height;
  foreach(var original in new[]{template,save?ui.saveGameWindow.saveButton:ui.loadGameWindow.loadButton})clear&=!ar.Overlaps(Bounds((RectTransform)original.transform))&&!br.Overlaps(Bounds((RectTransform)original.transform));
  var show=save?ui.saveGameWindow.showButton:ui.loadGameWindow.showButton;clear&=!ar.Overlaps(Bounds((RectTransform)show.transform))&&!br.Overlaps(Bounds((RectTransform)show.transform));
  // Checkbox graphics extend outside their parent rectangle. Inspect actual
  // visible children, including the adjacent game-goal control.
  if(!save){foreach(var group in new[]{ui.loadGameWindow.loadSandboxGroup,ui.loadGameWindow.goalLevelGroup}){clear&=group.activeInHierarchy;foreach(var graphic in group.GetComponentsInChildren<Graphic>()){if(!graphic.enabled||graphic.color.a<=0)continue;var rect=Bounds(graphic.rectTransform);clear&=!ar.Overlaps(rect)&&!br.Overlaps(rect);}}}
  Note((save?"save":"load")+" file buttons clear original controls",clear,ar+" / "+br+" surface="+Screen.width+"x"+Screen.height);
 }
 static IEnumerator FileClick(bool save,bool export){
  var b=DSPPadDocuments.FileButton(save,export);if(!b){Note("file button exists",false);yield break;}var rect=Bounds((RectTransform)b.transform);var point=rect.center;var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=point},hits);
  bool hit=hits.Count>0&&(hits[0].gameObject==b.gameObject||hits[0].gameObject.transform.IsChildOf(b.transform));Note((save?"save":"load")+(export?" export":" import")+" button receives pointer",hit);
  foreach(int mask in new[]{0,1,0}){float until=Time.realtimeSinceStartup+.2f;do{DSPAOTQueueTestPointer(point.x/Screen.width,point.y/Screen.height,mask,0,0,0);yield return null;}while(Time.realtimeSinceStartup<until);}
 }
 static IEnumerator Files(){
  string suffix=DSPPadDiagnosticLaunch.BuildVersion,name="Docs-Fixture-"+suffix;Note("source save created",GameSave.SaveCurrentGame(name));string save=Path.Combine(GameConfig.gameSaveFolder,name+GameSave.saveExt);long originalLength=new FileInfo(save).Length;
  UIRoot.instance.loadGameWindow._Open();yield return Wait();foreach(var e in UIRoot.instance.loadGameWindow.GetComponentsInChildren<UIGameSaveEntry>(true))if(e.saveName==name){UIRoot.instance.loadGameWindow.selected=e;break;}yield return Wait();Layout(false);yield return DSPPadRenderDiagnostics.Capture("documents-load-toolbar");int cancel=DSPPadDocuments.Cancelled;yield return FileClick(false,false);Note("system import request",DSPPadDocuments.Busy);yield return Wait(6);Note("system document picker presented",DSPPadDocuments.DSPAOTDocumentProbe(0,null)==1);DSPPadDocuments.DSPAOTDocumentProbe(3,"documents-import-picker.png");yield return Wait(.5f);DSPPadDocuments.DSPAOTDocumentProbe(1,null);yield return Done();Note("cancel preserves save",DSPPadDocuments.Cancelled==cancel+1&&new FileInfo(save).Length==originalLength);
  int count=DSPPadDocuments.Imported;Note("save import request",DSPPadDocuments.Open(GameConfig.gameSaveFolder,false));yield return Wait(1);DSPPadDocuments.DSPAOTDocumentProbe(2,save);yield return Wait(.3f);yield return Done();Note("native coordinated save import",DSPPadDocuments.Imported==count+1,DSPPadDocuments.LastMessage);string imported=DSPPadDocuments.LastImported;Note("duplicate save keeps both",imported!=save&&File.Exists(imported)&&new FileInfo(imported).Length==originalLength&&new FileInfo(save).Length==originalLength);
  GameSaveHeader header;GameSave.ReadHeader(Path.GetFileNameWithoutExtension(imported),false,out header);Note("original parser reads imported save",header!=null);
  string bad=Path.Combine(Application.persistentDataPath,"port-invalid.dsv");File.WriteAllText(bad,"invalid fixture");bool rejected=false;try{DSPPadDocuments.Import(bad,"invalid.dsv",GameConfig.gameSaveFolder);}catch(IOException){rejected=true;}Note("invalid save rejected",rejected&&!File.Exists(Path.Combine(GameConfig.gameSaveFolder,"invalid.dsv")));File.Delete(bad);
  yield return FileClick(false,true);Note("export browser request",DSPPadDocuments.Busy);yield return Wait(1);DSPPadDocuments.DSPAOTDocumentProbe(4,null);yield return Wait(6);Note("system export picker presented",DSPPadDocuments.DSPAOTDocumentProbe(0,null)==1);DSPPadDocuments.DSPAOTDocumentProbe(3,"documents-export-picker.png");yield return Wait(.5f);DSPPadDocuments.DSPAOTDocumentProbe(1,null);yield return Done();Note("export cancellation preserves source",new FileInfo(save).Length==originalLength);UIRoot.instance.loadGameWindow._Close();
  UIRoot.instance.saveGameWindow._Open();yield return Wait();Layout(true);yield return DSPPadRenderDiagnostics.Capture("documents-save-toolbar");
  foreach(bool export in new[]{false,true}){yield return FileClick(true,export);Note(export?"save export request":"save import request",DSPPadDocuments.Busy);yield return Wait(1);DSPPadDocuments.DSPAOTDocumentProbe(1,null);yield return Done();}UIRoot.instance.saveGameWindow._Close();
  Directory.CreateDirectory(GameConfig.blueprintFolder);var blueprint=new BlueprintData();blueprint.ResetAsEmpty();blueprint.primaryAreaIdx=0;blueprint.areas=new[]{new BlueprintArea{index=0,parentIndex=-1,areaSegments=200,width=2,height=2}};blueprint.buildings=new[]{new BlueprintBuilding{index=0,areaIndex=0,itemId=2201,modelIndex=(short)LDB.items.Select(2201).ModelIndex}};string bp=Path.Combine(GameConfig.blueprintFolder,"触控文件测试-"+suffix+".txt");File.WriteAllText(bp,blueprint.ToBase64String());UIRoot.instance.uiGame.OpenBlueprintBrowser();yield return Wait();yield return DSPPadRenderDiagnostics.Capture("documents-blueprint-toolbar");count=DSPPadDocuments.Imported;Note("blueprint import request",DSPPadDocuments.Open(GameConfig.blueprintFolder,false));yield return Wait(1);DSPPadDocuments.DSPAOTDocumentProbe(2,bp);yield return Wait(.3f);yield return Done();Note("native coordinated blueprint import",DSPPadDocuments.Imported==count+1,DSPPadDocuments.LastMessage);var verify=new BlueprintData();Note("original blueprint roundtrip",verify.LoadBlueprintData(DSPPadDocuments.LastImported)==BlueprintDataIOError.OK&&verify.buildings.Length==1&&verify.buildings[0].itemId==2201);
  rejected=false;try{DSPPadDocuments.Import(save,"wrong.dsv",GameConfig.blueprintFolder);}catch(IOException){rejected=true;}Note("cross-type import rejected",rejected);UIRoot.instance.uiGame.ShutBlueprintBrowser();
 }
 static IEnumerator Guard(string name,IEnumerator routine){report.phase=name;Write();var stack=new Stack<IEnumerator>();stack.Push(routine);while(stack.Count>0){bool more=false;object next=null;Exception failure=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception e){failure=e;}if(failure!=null){report.errors.Add(name+": "+failure);Write();break;}if(!more){(stack.Pop() as IDisposable)?.Dispose();continue;}if(next is IEnumerator){stack.Push((IEnumerator)next);continue;}yield return next;}while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();if(DSPPadDocuments.Busy){DSPPadDocuments.DSPAOTDocumentProbe(1,null);yield return Done();}}
 static IEnumerator LayoutOnly(){
  var ui=UIRoot.instance;ui.loadGameWindow._Open();yield return Wait();
  // Select an existing entry to reveal Sandbox and game-goal controls, without
  // loading, creating, importing or exporting a save.
  foreach(var e in ui.loadGameWindow.GetComponentsInChildren<UIGameSaveEntry>())if(!string.IsNullOrEmpty(e.saveName)){ui.loadGameWindow.selected=e;break;}
  yield return Wait();Layout(false);yield return DSPPadRenderDiagnostics.Capture("documents-load-toolbar");ui.loadGameWindow._Close();
  ui.saveGameWindow._Open();yield return Wait();Layout(true);yield return DSPPadRenderDiagnostics.Capture("documents-save-toolbar");ui.saveGameWindow._Close();
 }
 public static IEnumerator RunLayoutOnly(){
  if(!DSPPadDiagnosticLaunch.AutomaticActionsAllowed)yield break;
  reportFile="file-layout-audit.json";report=new Report{batchIdentifier=DSPPadDiagnosticLaunch.BatchIdentifier,buildVersion=DSPPadDiagnosticLaunch.BuildVersion,phase="begin",limits="Changed save-window button style and visible-control bounds only; existing file-provider/parser/input acceptance retained."};
  yield return Guard("layout",LayoutOnly());UIRoot.instance.loadGameWindow._Close();UIRoot.instance.saveGameWindow._Close();
  Passed=report.errors.Count==0&&report.checks.Count==4;foreach(var c in report.checks)Passed&=c.passed;report.phase=Passed?"passed":"failed";report.completed=true;Write();
 }
 public static IEnumerator Run(){if(!DSPPadDiagnosticLaunch.AutomaticActionsAllowed)yield break;reportFile="input-files-regression.json";report=new Report{batchIdentifier=DSPPadDiagnosticLaunch.BatchIdentifier,buildVersion=DSPPadDiagnosticLaunch.BuildVersion,phase="begin"};Write();yield return Guard("modes",Modes());yield return Guard("files",Files());Passed=report.errors.Count==0;foreach(var c in report.checks)Passed&=c.passed;report.phase=Passed?"passed":"failed";report.completed=true;Write();}
